    "content": "香港《南华早报》星期三（11月11日）引述消息人士报道，中国、美国和俄罗斯之间的会谈，可能促使三方承诺管控人工智能（AI）在核武器领域的应用。 据报道，中俄美三国过去数周持续磋商，争取敲定下周在深圳举行的亚太经合组织（APEC）领导人会议期间，三国领导人会谈的议程及礼宾安排。 消息人士向《南华早报》透露，俄乌战争和朝鲜半岛无核化等议题已基本不在考虑之列，各方转而聚焦可能达成共识的领域，尤其是AI在核武器指挥与控制体系中的作用。 消息人士也称，三国工作层级团队已讨论AI在关键武器系统中的应用，以及可能发表一份反对未来…"
