    "link": "https://m.thepaper.cn/newsDetail_forward_34450537",
    "pub_date": "2026-11-11 09:45:42",
    "author": "",
    "description": "#当地时间11月10日，《纽约时报》援引知情人士的话报道，由于受到来自伊朗的威胁，美国财政部长贝森特近期已搬离住所，转入一处军事基地居住。报道称，目前尚不清楚贝森特所面临威胁的具体严重程度。 美国财政部未立即回应置评请求。伊朗此前曾否认策划过针对美国本土官员及民众的袭击。",
    "content": "#当地时间11月10日，《纽约时报》援引知情人士的话报道，由于受到来自伊朗的威胁，美国财政部长贝森特近期已搬离住所，转入一处军事基地居住。报道称，目前尚不清楚贝森特所面临威胁的具体严重程度。 美国财政部未立即回应置评请求。伊朗此前曾否认策划过针对美国本土官员及民众的袭击。"
