    "content": "台湾媒体报道，台湾科技公司宏碁创办人施振荣将代表总统赖清德，出席下周在中国大陆深圳举行的亚太经济合作组织（APEC）峰会。这将是施振荣继2007年后，第二次担任台湾APEC领袖代表。 据台湾《自由时报》星期三（11月11日）报道，台湾总统府已锁定由施振荣出任今年APEC领袖代表，预计当天正式对外公布。 《联合报》同日报道，施振荣是目前呼声最高的人选，总统府预计本周举行记者会，说明相关安排。 现年81岁的施振荣是台湾科技业代表人物，曾于2007年陈水扁执政期间，代表台湾出席在澳大利亚悉尼举行的APEC峰会。由于熟悉国…"
