    "content": "视频编辑：张兆亿(14:45) 山东临沂河东区宏润塑料制品厂的门店里，高高垒起一捆捆包装好的塑料薄膜，上面标记着“工程膜”字样。但私下里，这些薄膜也可以被当作农用地膜出售。 澎湃新闻影子调查队今年8月下旬在这家门店探访时，老板谷女士一句话捅破了这套“身份游戏”：“工程膜不限厚度，农用膜（厚度）必须一丝以上。不可以标记是农用的，你（标）农用的，就查你，逮着就使劲罚。” 农用地膜是现代农业的重要生产资料之一，对农作物增产增收起到重要作用。我国对农用地膜制定有着严格标准，要求厚度不得小于0.01毫米，也就是行业上所说的1…"
