    "description": "在第九届进博会7.2号馆内，一辆1955年出厂的汽车首次来到中国。今年的“国际汽车文化展示区”升级为2.0版：展区面积比上届翻了一番，展车从11辆增至15辆，展品类型也从经典老车扩展到赛车、超跑。 记者：丁汀 新华社音视频部制作",
    "content": "在第九届进博会7.2号馆内，一辆1955年出厂的汽车首次来到中国。今年的“国际汽车文化展示区”升级为2.0版：展区面积比上届翻了一番，展车从11辆增至15辆，展品类型也从经典老车扩展到赛车、超跑。 记者：丁汀 新华社音视频部制作"
