    "content": "2026年11月11日 新华社北京11月10日电&nbsp;&nbsp;全国政协主席王沪宁10日在京会见老挝建国阵线中央委员会副主席布沙迪。 王沪宁表示，今年6月，习近平总书记、国家主席同通伦总书记、国家主席就构建新时代全天候中老命运共同体达成重要共识，为两国关系擘画宏伟蓝图。中方愿同老方遵循两党两国最高领导人战略指引，为推进各自社会主义现代化建设增添新动力。中国全国政协愿与老挝建国阵线深化交流合作，为推动中老命运共同体建设贡献力量。王沪宁还介绍了中共二十届五中全会情况。 布沙迪表示，老方祝贺中共二十届五中全会胜利…"
