    "description": "2026年11月11日 本报北京11月10日电 （记者欧阳洁）据海关统计，2026年前10月，我国货物贸易进出口总值44.81万亿元，同比增长20%。其中，出口25.99万亿元，同比增长17.6%；进口18.82万亿元，同比增长23.6%。10月，我国货物贸易进出口总值4.87万亿元，同比增长31.2%。 从贸易伙伴看，前10月，我国与东盟贸易总值为7.68万亿元，同比增长24.2%；我国与欧盟贸易总值为5.29万亿元，同比增长8.5%…",
    "content": "2026年11月11日 本报北京11月10日电&nbsp;&nbsp;（记者欧阳洁）据海关统计，2026年前10月，我国货物贸易进出口总值44.81万亿元，同比增长20%。其中，出口25.99万亿元，同比增长17.6%；进口18.82万亿元，同比增长23.6%。10月，我国货物贸易进出口总值4.87万亿元，同比增长31.2%。 从贸易伙伴看，前10月，我国与东盟贸易总值为7.68万亿元，同比增长24.2%；我国与欧盟贸易总值为5.29万亿元，同比增长8.5%。同期，我国对共建“一带一路”国家合计进出口22.88万亿…"
