    "content": "2026年11月11日 中共中央党史和文献研究院编辑的习近平同志《论减贫脱贫》一书，收入习近平同志2012年11月至2026年7月期间关于减贫脱贫的重要文稿55篇。现将这部专题文集的主要篇目介绍如下。 《人民对美好生活的向往，就是我们的奋斗目标》是2012年11月15日习近平同志在中共十八届中央政治局常委同中外记者见面时讲话的主要部分。指出，我们的人民热爱生活，期盼有更好的教育、更稳定的工作、更满意的收入、更可靠的社会保障、更高水平的医疗卫生服务、更舒适的居住条件、更优美的环境，期盼孩子们能成长得更好、工作得更好、…"
