    "description": "2026年11月11日 不久前，第四十七届世界葡萄与葡萄酒大会暨国际葡萄与葡萄酒组织（OIV）成员国代表大会在宁夏银川举办。“中国的葡萄酒品质优良，既蕴含了对中国独特风土的深刻理解，又彰显了对可持续发展的坚定承诺。”OIV总干事约翰·巴克说。 一杯葡萄酒从戈壁荒滩走向世界。大会现场发布的国际葡萄酒产品品牌榜显示，我国有19个产品品牌进入全球前100名，其中9个来自宁夏。今年前三季度，宁夏货物进出口总额达199.80亿元，同比增长24.9…",
