    "description": "2026年11月11日 新华社北京11月10日电 （记者曹嘉玥）中共中央政治局委员、外交部长王毅10日在北京同斯洛伐克外长布拉纳尔会谈。 王毅表示，近年来，在两国领导人共同引领下，中斯成为大小不同、制度不同国家友好相处、平等相待、合作共赢的范例。中方愿同斯方一道，进一步巩固政治互信，加强战略协调，充分释放合作潜力，以更高质量、更高水平双边关系为中欧关系健康发展及世界和平稳定作出贡献。 布拉纳尔祝贺中国共产党二十届五中全会成功召开，表示斯…",
    "content": "2026年11月11日 新华社北京11月10日电&nbsp;&nbsp;（记者曹嘉玥）中共中央政治局委员、外交部长王毅10日在北京同斯洛伐克外长布拉纳尔会谈。 王毅表示，近年来，在两国领导人共同引领下，中斯成为大小不同、制度不同国家友好相处、平等相待、合作共赢的范例。中方愿同斯方一道，进一步巩固政治互信，加强战略协调，充分释放合作潜力，以更高质量、更高水平双边关系为中欧关系健康发展及世界和平稳定作出贡献。 布拉纳尔祝贺中国共产党二十届五中全会成功召开，表示斯方始终视中国为重要伙伴，愿同中方拓展各领域交流合作。 20…"
