    "description": "2026年11月11日 在儿童心身医学门诊工作许多年，我发现，一种无形的绳结束缚着不少家庭。父母呵护备至、时刻兜底，拼尽全力为孩子规避所有挫折与不安，可越是用力守护，其脆弱与焦虑反而越发明显；孩子敏感、忐忑，害怕尝试、畏惧出错，甚至不敢社交、不愿求学，深陷情绪内耗。 对此，一些家长不解：倾尽温柔与付出，只想打造温暖港湾，为何反而加剧孩子焦虑？答案从来不在孩子单一的情绪问题里，而在整个家庭的情绪系统之中。与其忙于“扑灭”焦虑，不如在倾听中…",
    "content": "2026年11月11日 在儿童心身医学门诊工作许多年，我发现，一种无形的绳结束缚着不少家庭。父母呵护备至、时刻兜底，拼尽全力为孩子规避所有挫折与不安，可越是用力守护，其脆弱与焦虑反而越发明显；孩子敏感、忐忑，害怕尝试、畏惧出错，甚至不敢社交、不愿求学，深陷情绪内耗。 对此，一些家长不解：倾尽温柔与付出，只想打造温暖港湾，为何反而加剧孩子焦虑？答案从来不在孩子单一的情绪问题里，而在整个家庭的情绪系统之中。与其忙于“扑灭”焦虑，不如在倾听中解开绳结。 倾听，不是听自己想听的、期待的，而是听孩子真正在表达的。 现实中，这…"
