    "description": "2026年11月11日 金 鹏摄（影像中国） \"> 民政部、全国老龄办、中国老龄协会近日印发通知，提出面向独居、空巢、留守、失能等特殊困难老年人开展探访关爱服务。其中明确，将安全风险较高的特殊困难老年人作为重点对象，每两周至少探访1次；确有需要的，可进一步提高探访频次；到2028年底，探访关爱服务常态化开展，常态长效机制全面建立。 这正是： 敲门探访入户来， 老弱需求细细排。 嘘寒问暖勤看望， 长效机制暖心怀。 高世林文 2026-11…",
    "content": "2026年11月11日 浙江嘉兴市南湖区文纬里小区，医护人员上门为行动不便的老年人义诊。 金 鹏摄（影像中国） \"> 民政部、全国老龄办、中国老龄协会近日印发通知，提出面向独居、空巢、留守、失能等特殊困难老年人开展探访关爱服务。其中明确，将安全风险较高的特殊困难老年人作为重点对象，每两周至少探访1次；确有需要的，可进一步提高探访频次；到2028年底，探访关爱服务常态化开展，常态长效机制全面建立。 这正是： 敲门探访入户来， 老弱需求细细排。 嘘寒问暖勤看望， 长效机制暖心怀。 高世林文 2026-11-11 00:…"
