    "content": "2026年11月11日 今年是孙中山先生诞辰160周年。连日来，香港举办了一系列纪念活动。11月2日至7日，“从振兴中华到民族复兴——孙中山史迹展”举办，许多青年学生、社会团体和市民到场参观。 本次展览内容包括历史照片、珍贵文稿及历史影像资料、实物及书画作品等，追溯孙中山在香港留下的足迹。展览汇集了来自内地与香港共8家孙中山纪念机构的实物资料，生动还原了孙中山先生的家国情怀和日常细节。 香港大学学生小吴在“孙中山香港大学演讲”的历史图片前驻足良久。“看到这张历史照片，我感觉自己仿佛跨越时空，感受到了孙中山先生的爱国…"
