    "content": "2026年11月11日 本报北京11月10日电&nbsp;&nbsp;（记者刘博通）10日，以“新发展理念下的西藏数智化实践”为主题的第十届西藏智库国际论坛暨《数智化在西藏：共享与发展》新书发布会在北京举行。 论坛设置主旨演讲和3个专题报告分论坛，围绕新时代党的治藏方略实践成效、数智化赋能西藏现代化建设、数智化技术与优秀文化传承等议题展开研讨。 据介绍，《数智化在西藏：共享与发展》由中国社会科学院民族学与人类学研究所课题组基于在西藏地区的深入调研撰写而成。为配合国内市场阅读习惯，该书同步线上推出电子书、有声书，满足…"
