    "description": "2026年11月11日 近期，国务院总理李强签署国务院令，公布修订后的《基金会管理条例》（以下简称《条例》），自2027年1月1日起施行。司法部、民政部负责人就《条例》有关问题回答了记者提问。 问：请简要介绍一下《条例》修订的背景和总体思路。 答：党中央、国务院高度重视基金会管理工作。现行条例于2004年公布施行，在规范基金会登记管理、发展公益事业等方面发挥了重要作用。随着我国经济社会发展，基金会管理工作面临一些新情况新问题，如基金会内…",
    "content": "2026年11月11日 近期，国务院总理李强签署国务院令，公布修订后的《基金会管理条例》（以下简称《条例》），自2027年1月1日起施行。司法部、民政部负责人就《条例》有关问题回答了记者提问。 问：请简要介绍一下《条例》修订的背景和总体思路。 答：党中央、国务院高度重视基金会管理工作。现行条例于2004年公布施行，在规范基金会登记管理、发展公益事业等方面发挥了重要作用。随着我国经济社会发展，基金会管理工作面临一些新情况新问题，如基金会内部治理机制不健全、开展活动不够规范、综合监管力度还需加大等。慈善法对包括基金会在…"
