    "description": "2026年11月11日 习近平总书记强调：“要广泛开展国际合作，帮助全球南方国家加强能力建设，弥合数智鸿沟，促进可持续发展，避免在人工智能领域造成新的历史不公。”2024年7月，第七十八届联合国大会协商一致通过了中国主提的加强人工智能能力建设国际合作决议。这是全球首个聚焦人工智能能力建设的共识性文件，充分彰显中国对人工智能发展和治理的负责任态度和重要引领作用。“十五五”规划纲要提出：“推动建立各国广泛参与的人工智能治理框架，共同构建平权…",
    "content": "2026年11月11日 习近平总书记强调：“要广泛开展国际合作，帮助全球南方国家加强能力建设，弥合数智鸿沟，促进可持续发展，避免在人工智能领域造成新的历史不公。”2024年7月，第七十八届联合国大会协商一致通过了中国主提的加强人工智能能力建设国际合作决议。这是全球首个聚焦人工智能能力建设的共识性文件，充分彰显中国对人工智能发展和治理的负责任态度和重要引领作用。“十五五”规划纲要提出：“推动建立各国广泛参与的人工智能治理框架，共同构建平权、互信、多元、共赢的全球人工智能开放生态，支持全球南方国家加强人工智能能力建设。…"
