    "description": "2026年11月11日 习近平总书记强调：“要在推动高质量发展中强化就业优先导向。”“十五五”规划纲要提出，构建就业友好型发展方式。当前及未来一段时期，我国就业领域面临着多重挑战交织叠加的复杂局面，人口结构变化重塑劳动力供给新格局，数字化发展使灵活就业新就业形态不断增加，人工智能技术发展深刻影响劳动力市场。构建就业友好型发展方式，就是要把促进高质量充分就业目标深度融入宏观政策制定、产业规划和人力资本开发全过程，使高质量发展的过程成为就业…",
