    "description": "2026年11月11日 由人民日报社与福建省人民政府共同举办的第十二届东盟与中日韩媒体合作研讨会11月4日在福建福州举行。研讨会以“开放合作 共享发展”为主题，来自16个国家及国际组织、47家媒体和机构的120余名代表齐聚一堂，深入探讨媒体在区域合作中的责任与使命，凝聚起更广泛的合作共识。 “东盟与中日韩地缘相近、人文相通、利益相融，是全球最具活力和潜力的区域合作板块之一。当前，世界百年变局加速演进，全球经济复苏承压，地缘格局深刻调整，…",
    "content": "2026年11月11日 由人民日报社与福建省人民政府共同举办的第十二届东盟与中日韩媒体合作研讨会11月4日在福建福州举行。研讨会以“开放合作&nbsp;&nbsp;共享发展”为主题，来自16个国家及国际组织、47家媒体和机构的120余名代表齐聚一堂，深入探讨媒体在区域合作中的责任与使命，凝聚起更广泛的合作共识。 “东盟与中日韩地缘相近、人文相通、利益相融，是全球最具活力和潜力的区域合作板块之一。当前，世界百年变局加速演进，全球经济复苏承压，地缘格局深刻调整，科技变革日新月异，区域合作机遇与挑战并存。如何以开放纾解发…"
