    "description": "2026年11月11日 国之交在于民相亲，民相亲在于心相通。文明交流互鉴为高质量共建“一带一路”打下坚实的民意基础。 11月4日上午，2026“一带一路”媒体合作论坛的分论坛之一——2026丝路文明发展论坛在福建福州举行。来自中外媒体、政府部门、研究机构和企业界的代表齐聚一堂。 “一艘沉船就是一座博物馆。”武汉大学教授姜波以水下考古为线索展开讲述，“南海Ⅰ号”，南海西北陆坡一号、二号，市舶司遗址……一个个实证勾勒出海上丝绸之路的文明交流…",
    "content": "2026年11月11日 国之交在于民相亲，民相亲在于心相通。文明交流互鉴为高质量共建“一带一路”打下坚实的民意基础。 11月4日上午，2026“一带一路”媒体合作论坛的分论坛之一——2026丝路文明发展论坛在福建福州举行。来自中外媒体、政府部门、研究机构和企业界的代表齐聚一堂。 “一艘沉船就是一座博物馆。”武汉大学教授姜波以水下考古为线索展开讲述，“南海Ⅰ号”，南海西北陆坡一号、二号，市舶司遗址……一个个实证勾勒出海上丝绸之路的文明交流图景。 中亚地区是中国与欧亚国家文化交融、友好往来的重要枢纽。“2000余年的丝…"
