    "content": "2026年11月11日 有色金属行业三季报近日发布，两个数据值得关注：行业利润大幅增长76.5%，工业增加值同比下降0.8%。 如何看待这组反差？ 先看原因。利润增长，既有市场行情回暖的因素，也有产业自身降本增效的贡献。 前三季度，资源稀缺导致国际大宗商品价格上涨，叠加全球通胀、避险情绪升温等因素，具有金融属性的多种有色金属价格上涨，国内新兴产业发展带动部分金属需求增长，同时企业成本管控成效显现，百元营收成本费用同比下降，推动行业盈利水平提升。 工业增加值下降，则有统计口径和生产结构方面的原因。工业增加值增速按可比…"
